import networkx as nx
from itertools import combinations

def solve_small(n):
    # Create Moore graph
    G = nx.Graph()
    for r in range(n):
        for c in range(n):
            G.add_node((r, c))
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        G.add_edge((r, c), (nr, nc))

    # We want to find a subset of vertices S such that the induced subgraph G[S] has max degree 1.
    # This is equivalent to finding a maximum size induced subgraph with max degree 1.
    # This is a hard problem (maximum induced subgraph with property P).
    # For small n, we can use brute force or an ILP.

    import pulp
    prob = pulp.LpProblem("MaxK", pulp.LpMaximize)
    x = pulp.LpVariable.dicts("x", G.nodes(), cat=pulp.LpBinary)
    prob += pulp.lpSum([x[v] for v in G.nodes()])

    # Degree constraint: for each v, sum of x[u] for u in neighbors(v) <= 1 if x[v] = 1.
    # This can be written as: sum_{u in N(v)} x[u] <= 1 + M(1 - x[v])
    # where M is the maximum degree of G (which is 8).
    for v in G.nodes():
        neighbors = list(G.neighbors(v))
        prob += pulp.lpSum([x[u] for u in neighbors]) <= 8 * (1 - x[v]) + 1

    prob.solve(pulp.PULP_CBC_CMD(msg=0))
    return pulp.value(prob.objective)

for n in range(1, 6):
    print(f"n={n}, k={solve_small(n)}")

