        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                neighbors.append((nr, nc))
    return neighbors

def is_valid(S, n):
    for v in S:
        deg = 0
        for neighbor in get_moore_neighbors(n, v[0], v[1]):
            if neighbor in S:
                deg += 1
        if deg > 1:
            return False
    return True

def max_k(n):
    nodes = [(r, c) for r in range(n) for c in range(n)]
    import itertools
    for k in range(n*n, 0, -1):
        for S in itertools.combinations(nodes, k):
            if is_valid(set(S), n):
                return k
    return 0

